"""Data collection and the route-forecast research programme; no fitted forecasts."""
from __future__ import annotations

import gzip
import json
from pathlib import Path

from _report import T, e, line_chart, n

HERE = Path(__file__).resolve().parent


def table(heads, rows):
    return ('<div class="tw"><table><thead><tr>' + ''.join(f'<th>{e(x)}</th>' for x in heads)
            + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{x}</td>' for x in row)
                                                + '</tr>' for row in rows) + '</tbody></table></div>')


def load_collection():
    return json.loads((HERE / 'out/collection_summary.json').read_text())


def collection_section(s):
    d = load_collection()
    eu, regional = d['eu_routes'], d['regional']
    india, international = d['india_domestic'], d['india_international']
    scenarios = d['scenario_inputs']
    euro_url = 'https://ec.europa.eu/eurostat/cache/metadata/en/avia_pa_esms.htm'
    wpp_url = 'https://population.un.org/wpp/'
    imf_url = 'https://www.imf.org/external/datamapper/datasets/WEO'
    s.url(wpp_url, 'UN World Population Prospects 2024: population scenarios')
    s.url(imf_url, 'IMF World Economic Outlook: dated source projections')
    for source in eu['sources']:
        s.url(source['url'], 'Eurostat PAS_CRD monthly archive via DBnomics')
    for source in [india['source'], international['source']]:
        s.url(source['url'], 'DGCA city-pair data: public curated transcription')
    for source in scenarios['sources']:
        s.url(source['url'], 'UN / IMF scenario inputs: downloaded source')
    for item in regional.values():
        for source in item.get('sources', []):
            s.url(source['url'], 'Eurostat regional series via DBnomics archive')
    visa_urls = [x['source']['url'] for x in d['visa']['snapshots']]
    for url in visa_urls:
        s.url(url, 'Passport Index: dated curator snapshot')

    body = [f'<h2 id="collected-data">{T("Сначала данные: что уже собрано", "Data first: what has been collected", "Zuerst die Daten: was bereits vorliegt")}</h2>',
            f'<p>{T("Длинная история собрана отдельно от рабочего справочника. Обычный парсер Eurostat в проекте оставляет последние 36 месяцев, поэтому одной серверной выгрузки недостаточно для проверки десятилетнего горизонта. Здесь используется архив Eurostat через DBnomics: дата загрузки 2026 года не превращает наблюдения 2024 года в текущий поток.", "Long histories were collected separately from the production catalogue. The project's ordinary Eurostat parser retains 36 months, so a server export alone cannot support ten-year evaluation. This collection uses a Eurostat archive through DBnomics: a 2026 retrieval date does not make 2024 observations current traffic.", "Lange Zeitreihen wurden getrennt vom produktiven Bestand gesammelt. Der normale Eurostat-Parser des Projekts behält 36 Monate; ein Serverexport allein reicht daher nicht für Zehnjahrestests. Verwendet wird ein Eurostat-Archiv über DBnomics: Ein Abruf 2026 macht Beobachtungen von 2024 nicht zum aktuellen Verkehr.")}</p>']
    rows = [
        [T('Европа: пары аэропортов', 'Europe: airport pairs', 'Europa: Flughafenpaare'),
         f'{e(eu["first_month"])}–{e(eu["last_month"])}',
         T(f'{n(eu["pairs"])} пар; {n(eu["pair_months"])} паро-месяцев', f'{n(eu["pairs"])} pairs; {n(eu["pair_months"])} pair-months', f'{n(eu["pairs"])} Paare; {n(eu["pair_months"])} Paarmonate'),
         T('отчётчики DE, ES, FR, IT, NL; архив, а не вся Европа', 'reporters DE, ES, FR, IT, NL; an archive, not all Europe', 'Meldeländer DE, ES, FR, IT, NL; Archiv, nicht ganz Europa') + s.cite(euro_url, eu['sources'][0]['url'])],
        [T('Индия: внутренние пары городов', 'India: domestic city pairs', 'Indien: inländische Städtepaare'),
         f'{e(india["first_period"])}–{e(india["last_period"])}',
         T(f'{n(india["pairs"])} пар; {n(india["usable_pair_periods"])} пригодных паро-месяцев', f'{n(india["pairs"])} pairs; {n(india["usable_pair_periods"])} usable pair-months', f'{n(india["pairs"])} Paare; {n(india["usable_pair_periods"])} verwendbare Paarmonate'),
         T('публичная перепись таблиц DGCA; конфликтующие дубли исключены из расчётного значения', 'public transcription of DGCA tables; conflicting duplicates have no usable value', 'öffentliche Übertragung von DGCA-Tabellen; widersprüchliche Duplikate ohne Rechenwert') + s.cite(india['source']['url'])],
        [T('Индия: международные пары городов', 'India: international city pairs', 'Indien: internationale Städtepaare'),
         f'{e(international["first_period"])}–{e(international["last_period"])}',
         T(f'{n(international["pairs"])} пар; {n(international["usable_pair_periods"])} пригодных паро-кварталов', f'{n(international["pairs"])} pairs; {n(international["usable_pair_periods"])} usable pair-quarters', f'{n(international["pairs"])} Paare; {n(international["usable_pair_periods"])} verwendbare Paarquartale'),
         T('кварталы сохранены кварталами; названия городов ещё требуют согласования', 'quarters stay quarters; city names still need harmonisation', 'Quartale bleiben Quartale; Städtenamen müssen noch vereinheitlicht werden') + s.cite(international['source']['url'])],
    ]
    body.append(table([T('Набор', 'Dataset', 'Datensatz'), T('Период', 'Period', 'Zeitraum'), T('Объём', 'Coverage', 'Umfang'), T('Граница применимости', 'Scope limit', 'Geltungsgrenze')], rows))
    body.append(f'<p class="small">{T("Во внутренней индийской выгрузке целиком отсутствуют май 2021 и май 2024 года. Большой временной охват не означает полную историю каждой пары: при требовании пяти полных учебных лет ни одна из двух индийских панелей пока не даёт десятилетнего проверочного окна. Проверена публичная перепись DGCA; сверка с исходными бюллетенями ведомства остаётся отдельным шагом.", "The domestic Indian extract entirely lacks May 2021 and May 2024. A broad date range does not imply a complete history for every pair: requiring five full training years leaves neither Indian panel with a ten-year evaluation window. The public DGCA transcription was checked; comparison with the agency's original bulletins remains a separate step.", "In der indischen Inlandsdatei fehlen Mai 2021 und Mai 2024 vollständig. Ein langer Zeitraum bedeutet keine vollständige Reihe je Paar: Bei fünf vollständigen Trainingsjahren bietet keines der beiden indischen Panels bisher ein Zehnjahresprüffenster. Geprüft wurde die öffentliche DGCA-Übertragung; der Abgleich mit den Originalbulletins bleibt ein separater Schritt.")}</p>')
    body.append(f'<p>{T(
        f"Из европейской панели исключены {n(eu['excluded_non_airport_pairs'])} служебные и неоднозначные пары: неизвестные аэропорты, зоны управления воздушным движением, агрегаты нескольких аэропортов и самопары. Две стороны одного маршрута не складываются: для одного месяца берётся среднее двух сообщений, а расхождение сохраняется. Закрытый исторический аэропорт не удаляется только потому, что его нет в сегодняшнем справочнике.",
        f"The European panel excludes {n(eu['excluded_non_airport_pairs'])} administrative or ambiguous pairs: unknown airports, airspace-control areas, multi-airport aggregates and self-pairs. Two reporters of the same route are not summed: monthly reports are averaged and their disagreement retained. A historical airport is not discarded merely because it is absent from today's catalogue.",
        f"Aus der europäischen Paneldatei wurden {n(eu['excluded_non_airport_pairs'])} administrative oder mehrdeutige Paare entfernt: unbekannte Flughäfen, Luftraumkontrollgebiete, Flughafenaggregate und Selbstpaare. Zwei Meldungen derselben Strecke werden monatlich gemittelt, nicht addiert; ihre Abweichung bleibt erhalten. Ein historischer Flughafen wird nicht allein wegen seines Fehlens im heutigen Verzeichnis entfernt.")}</p>')
    body.append(f'<p class="small">{T("Это наблюдаемый перевозочный поток PAS_CRD, не полный спрос между городами. Отсутствующий месяц не означает нулевой спрос. Полные годовые суммы считаются только при наличии всех 12 месяцев; сезонные и неполные ряды сохраняются с признаками пропусков.", "These are observed PAS_CRD passenger flows, not total city-to-city demand. A missing month does not mean zero demand. Complete annual totals require all twelve months; seasonal and incomplete series are retained with missingness flags.", "Dies sind beobachtete PAS_CRD-Verkehre, nicht die gesamte Nachfrage zwischen Städten. Ein fehlender Monat bedeutet keine Nullnachfrage. Vollständige Jahressummen erfordern zwölf Monate; saisonale und unvollständige Reihen bleiben mit Fehlwertkennzeichen erhalten.")}{s.cite(euro_url)}</p>')

    body.append(f'<h3>{T("Доход, туризм и деловая активность: уже есть длинные признаки", "Income, tourism and business: longer feature histories", "Einkommen, Tourismus und Wirtschaft: längere Merkmalsreihen")}</h3>')
    labels = {
        'gdp': T('Региональный ВВП на человека', 'Regional GDP per person', 'Regionales BIP je Einwohner'),
        'pop': T('Население региона', 'Regional population', 'Regionale Bevölkerung'),
        'emp': T('Занятость по отраслям', 'Employment by industry', 'Beschäftigung nach Branchen'),
        'nights': T('Месячные ночёвки', 'Monthly accommodation nights', 'Monatliche Übernachtungen'),
    }
    feature_rows = []
    for key, item in regional.items():
        source_urls = [x['url'] for x in item.get('sources', [])]
        feature_rows.append([labels[key], f'{e(item["first_period"])}–{e(item["last_period"])}', n(item['regions']), n(item['observations']) + s.cite(*source_urls[:1])])
    body.append(table([T('Показатель', 'Feature', 'Merkmal'), T('Период', 'Period', 'Zeitraum'), T('Регионов', 'Regions', 'Regionen'), T('Наблюдений', 'Observations', 'Beobachtungen')], feature_rows))
    body.append(f'<p>{T("Покрытие неодинаково по годам: например, население за 2025 год есть лишь у части регионов. Региональный ВВП в PPS на человека ещё нельзя трактовать как однородный реальный рост дохода во времени; нужны проверка единиц, ценовой базы и изменений границ NUTS. Отрасли услуг M и N опубликованы объединённо как M_N. Доход страны и население из Всемирного банка — отдельная история текущей редакции, а не прогноз будущего.", "Coverage differs by year: 2025 population is available for only some regions. Regional GDP per person in PPS is not automatically a homogeneous real-income growth series; units, price basis and NUTS boundary changes need checking. Service industries M and N are published jointly as M_N. World Bank income and population histories are current-revision historical data, not future forecasts.", "Die Abdeckung unterscheidet sich nach Jahr; Bevölkerung 2025 liegt beispielsweise nur für einige Regionen vor. Regionales BIP je Einwohner in PPS ist nicht automatisch eine homogene Reihe realer Einkommenszuwächse; Einheiten, Preisbasis und NUTS-Grenzänderungen sind zu prüfen. Dienstleistungsbranchen M und N werden gemeinsam als M_N veröffentlicht. Weltbankreihen zu Einkommen und Bevölkerung sind historische Daten aktueller Revision, keine Zukunftsprognosen.")}</p>')
    body.append(f'<p>{T(
        f"По визам собраны {n(len(d['visa']['snapshots']))} датированных снимков за {e(d['visa']['historical_start'])}–{e(d['visa']['historical_end'])}. Это наблюдения публичного составителя: дату снимка нельзя выдавать за дату вступления закона в силу, а правила по гражданству — за гражданство пассажиров маршрута. Старые кодировки ещё нужно согласовать. Таблица двусторонних диаспор ООН пока не получена; эффект диаспоры не оценён.",
        f"Visa inputs now include {n(len(d['visa']['snapshots']))} dated snapshots from {e(d['visa']['historical_start'])} to {e(d['visa']['historical_end'])}. These are public-curator observations: snapshot dates are not legal effective dates, and citizenship rules do not identify route passengers' citizenship. Legacy codes still need harmonisation. The UN bilateral migrant-stock table has not yet been obtained; no diaspora effect has been estimated.",
        f"Für Visa liegen {n(len(d['visa']['snapshots']))} datierte Aufnahmen von {e(d['visa']['historical_start'])} bis {e(d['visa']['historical_end'])} vor. Es sind Beobachtungen eines öffentlichen Datenpflegers: Aufnahmedaten sind keine gesetzlichen Inkrafttretensdaten, und Staatsangehörigkeitsregeln bestimmen nicht die Staatsangehörigkeit der Passagiere. Alte Codes müssen harmonisiert werden. Die bilaterale UN-Migrantenbestandsmatrix fehlt noch; ein Diasporaeffekt wurde nicht geschätzt.")}{s.cite(*visa_urls[-1:])}</p>')

    body.append(f'<h3>{T("Один маршрут в длинной истории", "One route across a long history", "Eine Strecke über einen langen Zeitraum")}</h3>')
    annual = {int(year): row['pax'] / 1000 for year, row in eu['example']['annual'].items() if row['months'] == 12}
    body.append('<style>.demand-history-scroll{max-width:100%;overflow-x:auto}.demand-history-scroll .chart{min-width:620px}</style><div class="demand-history-scroll">' + line_chart([(T('Франкфурт — Барселона', 'Frankfurt–Barcelona', 'Frankfurt–Barcelona'), 'var(--sky-t)', annual, False)],
                           ylab=T('тыс. пассажиров за год, обе стороны', 'thousand passengers/year, both directions', 'Tsd. Passagiere/Jahr, beide Richtungen'), x_every=4) + '</div>')
    body.append(f'<p class="small">{T("На узком экране график прокручивается по горизонтали.", "On a narrow screen, the chart scrolls horizontally.", "Auf schmalen Bildschirmen lässt sich das Diagramm horizontal verschieben.")}</p>')
    body.append(f'<p class="small">{T("EDDF–LEBL, архивный ряд 2005–2024. График показывает опубликованный поток, включая пандемический провал. Он не продолжен расчётным ростом до 2036 года. Изменения определения и отчётности проверяются до обучения.", "EDDF–LEBL, archived 2005–2024 series. The chart shows published flow, including the pandemic collapse. It is not extended with assumed growth to 2036. Definition and reporting changes must be checked before fitting.", "EDDF–LEBL, Archivreihe 2005–2024. Das Diagramm zeigt veröffentlichten Verkehr einschließlich des Pandemieeinbruchs. Es wird nicht mit angenommenem Wachstum bis 2036 verlängert. Definitions- und Meldeänderungen werden vor der Schätzung geprüft.")}{s.cite(*[x['url'] for x in eu['sources'] if x['cache_name'].endswith('00000')][:2])}</p>')

    body.append(f'<h2 id="forecast-horizons">{T("3, 5 и 10 лет: что уже можно проверить", "Three, five and ten years: what can now be tested", "Drei, fünf und zehn Jahre: was sich nun prüfen lässt")}</h2>')
    rows = []
    for horizon in ('3', '5', '10'):
        x = eu['readiness']['horizons'][horizon]
        years = [r['origin_year'] for r in x['origins']]
        rows.append([horizon, str(2026 + int(horizon)), f'{min(years)}–{max(years)}' if years else '—', n(x['n_origins']), n(x['sum_complete_pair_targets'])])
    body.append(table([T('Горизонт, лет', 'Horizon, years', 'Horizont, Jahre'), T('Цель выпуска 2026', 'Target from a 2026 issue', 'Ziel eines Stands 2026'), T('Последний учебный год', 'Last training year', 'Letztes Trainingsjahr'), T('Точек отсчёта', 'Candidate origins', 'Mögliche Ausgangspunkte'), T('Полных пар × целей', 'Complete pair-targets', 'Vollständige Paar-Ziele')], rows))
    body.append(f'<p>{T("В таблице подсчитаны кандидатные проверки, а не точность готового прогноза. Для каждой точки отсчёта требуются пять полных учебных лет, заканчивающихся указанным годом. Состав пар фиксируется по информации периода обучения; исчезнувший или неполный ряд в целевом году получает отдельный статус и не превращается в ноль. Окна перекрываются и не являются независимыми экспериментами. Для десятилетнего теста лишь один целевой год — 2019 — предшествует пандемии.", "The table counts candidate evaluations, not achieved forecast accuracy. Each origin requires five complete training years ending in the stated year. Pair eligibility is fixed using the training period; missing or incomplete target series receive a separate status rather than zero. Windows overlap and are not independent experiments. Only one ten-year target year, 2019, precedes the pandemic.", "Die Tabelle zählt mögliche Prüfungen, nicht erreichte Prognosegenauigkeit. Jeder Ausgangspunkt verlangt fünf vollständige Trainingsjahre bis einschließlich des genannten Jahres. Die Paarauswahl beruht auf dem Trainingszeitraum; fehlende oder unvollständige Zielreihen erhalten einen eigenen Status statt null. Die Fenster überlappen und sind nicht unabhängig. Nur ein Zieljahr des Zehnjahrestests, 2019, liegt vor der Pandemie.")}</p>')
    body.append(f'<p>{T("Исторические редакции всех признаков пока не восстановлены. Проверка на нынешней версии архива будет ретроспективной: она не докажет, что такой прогноз был доступен участнику рынка в тот год. Для выпуска 2026 года также нужен явный переход от последнего полного наблюдения к оценке текущего года, и только затем — горизонт 2029, 2031 или 2036.", "Historical vintages of every feature are not yet reconstructed. Testing today's archive is retrospective; it does not prove the forecast was available to a market participant at that date. A 2026 issue also needs an explicit bridge from the last complete observation to a current-year estimate before forecasting 2029, 2031 or 2036.", "Historische Datenstände sämtlicher Merkmale sind noch nicht rekonstruiert. Tests mit dem heutigen Archiv bleiben retrospektiv und belegen keine damalige Verfügbarkeit einer Prognose. Ein Stand 2026 braucht zudem einen expliziten Übergang von der letzten vollständigen Beobachtung zur Schätzung des laufenden Jahres, bevor 2029, 2031 oder 2036 prognostiziert werden.")}</p>')
    body.append(f'<p>{T("Если исходный факт заканчивается 2024 годом, до целей 2029/2031/2036 от него остаётся 5/7/12 лет. Поэтому оценка недостающих 2025–2026 годов добавляет собственную неопределённость и показывается отдельно. Год публикации исследования не обнуляет возраст данных.", "If the observed baseline ends in 2024, the 2029/2031/2036 targets are five/seven/twelve years away from that observation. Estimating missing 2025–2026 adds its own uncertainty and must be shown separately. Publication year does not reset the age of the data.", "Endet die beobachtete Basis 2024, liegen die Ziele 2029/2031/2036 fünf/sieben/zwölf Jahre danach. Die Schätzung fehlender Jahre 2025–2026 bringt eigene Unsicherheit mit und muss separat erscheinen. Das Veröffentlichungsjahr setzt das Datenalter nicht zurück.")}</p>')
    body.append(f'<h3>{T("Будущие входы — отдельно от истории", "Future inputs are separate from history", "Zukünftige Eingaben getrennt von der Historie")}</h3>')
    coverage = scenarios['coverage_by_source_variant_year']
    rows = []
    for year in (2029, 2031, 2036):
        rows.append([str(year), n(coverage['WPP_Medium'][str(year)]) + T(' стран/территорий, Medium/Low/High', ' countries/territories, Medium/Low/High', ' Länder/Gebiete, Medium/Low/High'),
                     n(coverage['WEO_NGDP_RPCH'].get(str(year), 0)) + T(' стран: рост реального ВВП', ' countries: real GDP growth', ' Länder: reales BIP-Wachstum') if str(year) in coverage['WEO_NGDP_RPCH'] else T('нет; нужен отдельный сценарий', 'unavailable; requires a separate scenario', 'nicht vorhanden; eigenes Szenario erforderlich')])
    body.append(table([T('Год', 'Year', 'Jahr'), 'UN WPP 2024', e(scenarios['weo_edition'])], rows))
    body.append(f'<p>{T("Варианты населения ООН и центральный прогноз МВФ — внешние входы сценария, а не наш прогноз авиапассажиров. Нельзя умножить каждый маршрут на рост ВВП и назвать это проверенной моделью. Для 2036 года нужны явно заданные экономические, транспортные и технологические сценарии. Варианты Low/High WPP сами по себе не образуют доверительный интервал спроса.", "UN population variants and the IMF central projection are external scenario inputs, not our passenger forecast. Multiplying every route by GDP growth does not create a validated model. For 2036, economic, transport and technology assumptions must be explicit. WPP Low/High variants are not, by themselves, a passenger-demand confidence interval.", "UN-Bevölkerungsvarianten und die zentrale IWF-Projektion sind externe Szenarioeingaben, keine eigene Passagierprognose. Jede Strecke mit BIP-Wachstum zu multiplizieren erzeugt kein validiertes Modell. Für 2036 müssen Wirtschafts-, Verkehrs- und Technologieannahmen explizit sein. WPP Low/High bilden allein kein Konfidenzintervall der Passagiernachfrage.")}{s.cite(wpp_url, imf_url)}</p>')
    return ''.join(body)


def forecast_programme(s):
    eu = load_collection()['eu_routes']
    panel = json.loads(gzip.decompress((HERE / 'out/eu_monthly_panel.json.gz').read_bytes()))
    examples = [
        ('EDDF-LEBL', T('Франкфурт — Барселона', 'Frankfurt–Barcelona', 'Frankfurt–Barcelona'), T('городской и пересадочный рынок', 'city and connecting market', 'Städte- und Umsteigemarkt')),
        ('EDDL-LEPA', T('Дюссельдорф — Пальма', 'Düsseldorf–Palma', 'Düsseldorf–Palma'), T('сезонный туристический рынок', 'seasonal leisure market', 'saisonaler Urlaubsmarkt')),
        ('EDDF-LIMC', T('Франкфурт — Милан-Мальпенса', 'Frankfurt–Milan Malpensa', 'Frankfurt–Mailand-Malpensa'), T('деловая активность и соседние аэропорты', 'business activity and nearby airports', 'Wirtschaftsaktivität und benachbarte Flughäfen')),
        ('EDDF-VIDP', T('Франкфурт — Дели', 'Frankfurt–Delhi', 'Frankfurt–Delhi'), T('дальний рынок и пересадки', 'long-haul market and connections', 'Langstreckenmarkt und Umstiege')),
        ('EHAM-LFRN', T('Амстердам — Ренн', 'Amsterdam–Rennes', 'Amsterdam–Rennes'), T('небольшой поток и подпитка узла', 'thin traffic and hub feed', 'geringer Verkehr und Hub-Zubringer')),
    ]
    body = [f'<h2 id="route-programme">{T("Цель: от прогноза рынка к маршруту и типу ВС", "The goal: from market forecasts to routes and aircraft", "Das Ziel: von Marktprognosen zu Strecken und Flugzeugtypen")}</h2>',
            f'<p>{T("Конечный результат исследования — карточки конкретных рынков на 2029, 2031 и 2036 годы. В каждой: наблюдаемый поток и дата базы, прогноз или сценарий с диапазоном, профиль по месяцам, возможная доля перевозчика, частота, допустимые типы ВС и экономика рейсов. Для нового прямого маршрута отдельно потребуется оценка перетока с пересадок, конкурентов и наземного транспорта.", "The intended result is a set of concrete market cards for 2029, 2031 and 2036. Each should include observed flow and its date, a forecast or scenario range, monthly profile, attainable airline share, frequency, feasible aircraft and flight economics. A new nonstop route additionally requires diversion from connecting services, competitors and surface transport.", "Ziel sind konkrete Marktkarten für 2029, 2031 und 2036: beobachteter Verkehr mit Datenstand, Prognose oder Szenariospanne, Monatsprofil, erreichbarer Airline-Anteil, Frequenz, geeignete Flugzeuge und Flugwirtschaft. Eine neue Direktverbindung erfordert zusätzlich die Verlagerung von Umsteigeangeboten, Wettbewerbern und Bodenverkehr.")}</p>',
            f'<h3>{T("Первые контрольные направления", "Initial diagnostic routes", "Erste Kontrollstrecken")}</h3>',
            f'<p>{T("Ниже — уже присутствующие в собранной панели пары разного масштаба. Это примеры для проверки метода, а не рейтинг привлекательности и не рекомендации открытия. Названия рыночных профилей — рабочие гипотезы, которые ещё нужно проверить данными.", "These pairs are already present in the collected panel and cover different traffic scales. They are diagnostic examples, not an attractiveness ranking or launch recommendations. Market-profile labels are working hypotheses to test with data.", "Diese Paare sind im gesammelten Panel vorhanden und decken unterschiedliche Verkehrsgrößen ab. Sie dienen der Methodenprüfung, nicht als Attraktivitätsrangliste oder Eröffnungsempfehlung. Die Marktprofile sind Arbeitshypothesen für die Datenprüfung.")}</p>']
    rows = []
    for code, label, hypothesis in examples:
        records = [r for r in panel['pairs'].get(code, []) if r[0].startswith('2024-')]
        total = n(sum(r[1] for r in records)) if len(records) == 12 else '—'
        rows.append([e(label) + '<br><span class="small">' + e(code) + '</span>', total, hypothesis])
    body.append(table([T('Пара', 'Pair', 'Paar'), T('Пассажиры 2024, обе стороны', '2024 passengers, both ways', 'Passagiere 2024, beide Richtungen'), T('Что проверяем', 'What to investigate', 'Prüffrage')], rows))
    body.append(f'<p class="small">{T("Числа вычислены из 12 месячных записей той же панели. Частоты и доли рынка ещё не оценены. Европейские и индийские пары анализируются отдельными выборками: аэропорт и город — разные единицы.", "Numbers sum twelve monthly observations in the same panel. Frequencies and market shares have not yet been estimated. European and Indian pairs form separate cohorts: airports and cities are different units.", "Die Werte summieren zwölf Monatsbeobachtungen desselben Panels. Frequenzen und Marktanteile sind noch nicht geschätzt. Europäische und indische Paare bleiben getrennte Stichproben: Flughafen und Stadt sind unterschiedliche Einheiten.")}{s.cite(eu['sources'][0]['url'])}</p>')
    body.append(table([T('Этап', 'Stage', 'Stufe'), T('Проверяемый результат', 'Reviewable output', 'Prüfbares Ergebnis')], [
        [T('1. Согласовать историю', '1. Harmonise history', '1. Historie vereinheitlichen'), T('идентификаторы аэропортов и городов, редакции NUTS, единицы и пропуски; свежий хвост 2024–2026 отдельно от архива', 'airport and city IDs, NUTS editions, units and missingness; a fresh 2024–2026 tail separate from the archive', 'Flughafen- und Stadt-IDs, NUTS-Stände, Einheiten und Fehlwerte; aktueller Zeitraum 2024–2026 getrennt vom Archiv')],
        [T('2. Сильная базовая модель', '2. Strong baselines', '2. Belastbare Basismodelle'), T('прошлый год, простой тренд и рабочая P/T/F-модель на одинаковых парах и временных разбиениях', 'last year, a simple trend and production P/T/F under identical pair and time splits', 'Vorjahr, einfacher Trend und produktives P/T/F auf identischen Paaren und Zeitaufteilungen')],
        [T('3. Проверить факторы', '3. Test the drivers', '3. Einflussgrößen prüfen'), T('доход, ночёвки, деловая активность, диаспоры и визы по одному и вместе; сохранять только устойчивый выигрыш', 'income, nights, business activity, diaspora and visas separately and jointly; retain robust gains', 'Einkommen, Nächte, Wirtschaft, Diaspora und Visa einzeln und gemeinsam; robuste Verbesserungen behalten')],
        [T('4. Сезон и горизонты', '4. Seasonality and horizons', '4. Saisonalität und Horizonte'), T('месячный профиль и интервалы отдельно для 3/5/10 лет; кризисы, открытия и исчезновения пар проверять явно', 'monthly profiles and intervals separately for 3/5/10 years; explicitly evaluate crises, openings and disappearing pairs', 'Monatsprofile und Intervalle getrennt für 3/5/10 Jahre; Krisen, Eröffnungen und verschwindende Paare ausdrücklich prüfen')],
        [T('5. Маршрут и расписание', '5. Route and schedule', '5. Strecke und Flugplan'), T('достижимая доля при заданных частоте, тарифе и конкуренции; затем кресла, тип ВС, налёт и экономика', 'attainable share given frequency, fare and competition; then seats, aircraft type, utilisation and economics', 'erreichbarer Anteil bei Frequenz, Tarif und Wettbewerb; danach Sitze, Flugzeugtyp, Nutzung und Wirtschaftlichkeit')],
    ]))
    body.append(f'<h3>{T("Как появится выбор самолёта", "How aircraft selection will enter", "Wie die Flugzeugauswahl hinzukommt")}</h3>')
    body.append(f'<p>{T("Малый поток сам по себе не доказывает, что нужен турбовинтовой самолёт: значение имеют расстояние, частота, расписание пересадок, требования аэродромов и цена владения. Планируем сравнивать допустимые комбинации «тип — кресла — частота», от ATR 72 и региональных реактивных до A320neo/737 MAX и дальнемагистральных типов. Это набор кандидатов для расчёта, а не назначение типов перечисленным маршрутам.", "Thin traffic alone does not establish that a turboprop is suitable: distance, frequency, connecting schedules, airport constraints and ownership costs matter. The planned comparison covers feasible type–seats–frequency combinations, from ATR 72 and regional jets to A320neo/737 MAX and long-haul aircraft. These are calculation candidates, not assignments to the routes listed above.", "Geringer Verkehr allein macht einen Turboprop nicht zur richtigen Wahl: Entfernung, Frequenz, Anschlusszeiten, Flughafenanforderungen und Besitzkosten zählen ebenfalls. Geplant ist der Vergleich zulässiger Kombinationen aus Typ, Sitzen und Frequenz — von ATR 72 und Regionaljets bis A320neo/737 MAX und Langstreckenflugzeugen. Dies sind Rechenkandidaten, keine Zuordnungen zu den genannten Strecken.")}</p>')
    body.append('<p class="formula">Q<sub>airline,m</sub> = share<sub>m</sub> × Q<sub>market,m</sub><br>'
                'flights<sub>m,one-way</sub> = Q<sub>airline,m</sub> / (2 × seats × load)<br>'
                'aircraft-hours<sub>m</sub> = 2 × flights<sub>m,one-way</sub> × block-hours</p>')
    body.append(f'<p>{T("Это только связка величин для симметричного потока в обе стороны. В модели доля и загрузка должны согласовываться с предложением кресел, а частота — быть целой и выполнимой по расписанию; при асимметрии направления считаются отдельно. Вместе с потоком проверяются диапазоны лизинга, топлива и налёта. Итогом должен стать устойчивый к сценариям набор вариантов, а не один тип ВС из одной точки прогноза.", "These identities only connect a symmetric two-way flow to capacity. In the model, share and load must be consistent with seat supply, frequencies integer and schedulable, and asymmetric directions evaluated separately. Lease, fuel and utilisation ranges accompany traffic scenarios. The intended output is a set of options robust across scenarios, not one aircraft selected from one point forecast.", "Diese Beziehungen verbinden lediglich einen symmetrischen Verkehr in beiden Richtungen mit Kapazität. Anteil und Auslastung müssen zum Sitzangebot passen, Frequenzen ganzzahlig und planbar sein; asymmetrische Richtungen werden getrennt gerechnet. Leasing-, Treibstoff- und Nutzungsbandbreiten begleiten die Verkehrsszenarien. Ziel sind szenariorobuste Optionen statt eines Typs aus einer einzelnen Punktprognose.")}</p>')
    body.append(f'<p>{T("В калькуляторе для этого понадобятся год и сценарий, дата наблюдений, месячный спрос и его проверенный диапазон, предположение о доле перевозчика, сравнение типов и частот и видимое объяснение каждого множителя. Статистика, оценка текущего года и прогноз будущего будут иметь разные подписи. Коэффициенты попадут в рабочий расчёт после проверки; новых обученных прогнозов на 2029/2031/2036 этот этап ещё не выпускает.", "The calculator will need year and scenario controls, observation date, monthly demand with a validated range, an airline-share assumption, type and frequency comparisons, and an explanation of each factor. Observed statistics, current-year estimates and future forecasts need distinct labels. Coefficients enter production after validation; this stage does not yet issue newly fitted 2029/2031/2036 forecasts.", "Der Rechner benötigt dafür Jahr und Szenario, Beobachtungsdatum, monatliche Nachfrage mit validierter Spanne, eine Airline-Anteilsannahme, Typ- und Frequenzvergleiche sowie eine Erklärung jedes Faktors. Statistik, Schätzung des laufenden Jahres und Zukunftsprognose erhalten unterschiedliche Bezeichnungen. Koeffizienten kommen nach Prüfung in die Produktion; diese Stufe liefert noch keine neu geschätzten Prognosen für 2029/2031/2036.")}</p>')
    return ''.join(body)
